diff --git a/lib/vtls/openssl.c b/lib/vtls/openssl.c
index f788c50cf7..8c8f43e836 100644
--- a/lib/vtls/openssl.c
+++ b/lib/vtls/openssl.c
@@ -3794,10 +3794,11 @@ static CURLcode ossl_connect_step1(struct Curl_cfilter *cf,
   }
 #endif

   SSL_set_app_data(backend->handle, cf);

+  connssl->reused_session = FALSE;
   if(ssl_config->primary.sessionid) {
     Curl_ssl_sessionid_lock(data);
     if(!Curl_ssl_getsessionid(cf, data, &ssl_sessionid, NULL)) {
       /* we got a session id, use it! */
       if(!SSL_set_session(backend->handle, ssl_sessionid)) {
@@ -3807,10 +3808,11 @@ static CURLcode ossl_connect_step1(struct Curl_cfilter *cf,
                             sizeof(error_buffer)));
         return CURLE_SSL_CONNECT_ERROR;
       }
       /* Informational message */
       infof(data, "SSL reusing session ID");
+      connssl->reused_session = TRUE;
     }
     Curl_ssl_sessionid_unlock(data);
   }

   backend->bio_method = ossl_bio_cf_method_create();
@@ -4338,11 +4340,12 @@ static CURLcode servercert(struct Curl_cfilter *cf,

   infof_certstack(data, backend->handle);

 #if (OPENSSL_VERSION_NUMBER >= 0x0090808fL) && !defined(OPENSSL_NO_TLSEXT) && \
   !defined(OPENSSL_NO_OCSP)
-  if(conn_config->verifystatus) {
+  if(conn_config->verifystatus && !connssl->reused_session) {
+    /* don't do this after Session ID reuse */
     result = verifystatus(cf, data);
     if(result) {
       X509_free(backend->server_cert);
       backend->server_cert = NULL;
       return result;

